// HostServiceServer is the server API for HostService service.
// All implementations must embed UnimplementedHostServiceServer
// for forward compatibility
type HostServiceServer interface {
	SetAccountAutomaticState(context.Context, *SetAccountAutomaticStateRequest) (*SetAccountAutomaticStateResponse, error)
	ReadObservationMetrics(context.Context, *ReadObservationMetricsRequest) (*ReadObservationMetricsResponse, error)
	// sticky.clear (grant "sticky.clear"): delete a share of the sticky session
	// bindings that point at an account and could serve (group_id, model), so
	// those sessions pick an account again on their next request (CONTRACTS
	// §74.2).
	ClearStickyBindings(context.Context, *ClearStickyBindingsRequest) (*ClearStickyBindingsResponse, error)
	// environment (always granted): the resolved environment variables of a
	// group and optionally an account, for work outside a gateway request
	// (CONTRACTS §74.3). Requests carry theirs in RequestMeta.environment.
	GetEnvironment(context.Context, *GetEnvironmentRequest) (*GetEnvironmentResponse, error)
	// settings (always granted): the effective values of sections of the
	// system settings, for work outside a gateway request (CONTRACTS §107).
	// values_json holds the fields CONTRACTS lists for the section, never a
	// secret; version changes exactly when the values do. No sections asks
	// for all of them; an unknown section is INVALID_ARGUMENT. Changes are
	// announced to every plugin process by PluginService.SettingsChanged.
	GetSettings(context.Context, *GetSettingsRequest) (*GetSettingsResponse, error)
	// users.read (grant "users.read"): basic facts of console users by id, to
	// check that a user exists or to show who they are (CONTRACTS §75.3). At
	// most 500 ids per call; unknown and deleted users are left out.
	GetUsers(context.Context, *GetUsersRequest) (*GetUsersResponse, error)
	// notify.send (grant "notify.send"): the notification channels of the
	// enabled plugins, and sending through one by its id; the core queues,
	// deduplicates, rate limits and retries (CONTRACTS §74.4).
	ListNotificationChannels(context.Context, *ListNotificationChannelsRequest) (*ListNotificationChannelsResponse, error)
	Notify(context.Context, *NotifyRequest) (*NotifyResponse, error)
	// Pure local tokenization. No upstream traffic and no billing side effects.
	CountTokens(context.Context, *CountTokensRequest) (*CountTokensResponse, error)
	// The host's HTTP client for one PlatformService.Execute call (relay) and
	// for Execute and Monitor calls (ExecuteHTTP, the fetch form). A plugin
	// opens no socket: it describes the request and the host sends it under
	// the account of the call - its proxy, transport, SSRF guard, timeouts
	// and the operator's header settings. Authority is the call's
	// execution token, bound to the calling process, the selected account and
	// immutable attribution, and void once the call returns. No monetary
	// amount, user identity or account selector is accepted, and the host
	// never retries: retry and failover are its own decision per attempt.
	//
	// RelayUpstream hands over the FINAL upstream request of the execution;
	// the upstream's answer goes to the client, never to the plugin. At most
	// one per execution, in one of two forms:
	//   - wait = false: the host validates the request (URL and its host,
	//     SSRF name check, headers) and answers at once with an empty
	//     response. Nothing is sent until Execute returns
	//     host_usage; the host then sends, relays and reads the usage by the
	//     declared rules. An Execute that fails or returns anything else
	//     after this leaves the request unsent.
	//   - wait = true: the host sends and relays now and answers when the
	//     exchange has ended, with the observation of a successful answer
	//     (the whole body, or the listed events of a stream) or the facts of
	//     a failed one. Only for executions whose
	//     ExecuteRequest sets extract_usage or task_submission; otherwise
	//     FAILED_PRECONDITION.
	// A request the host refuses is INVALID_ARGUMENT and counts as not relayed.
	RelayUpstream(context.Context, *RelayUpstreamRequest) (*RelayUpstreamResponse, error)
	// log (always granted)
	Log(context.Context, *LogRequest) (*LogResponse, error)
	// kv (grant "kv"): Redis-backed, namespaced per plugin.
	KVGet(context.Context, *KVGetRequest) (*KVGetResponse, error)
	KVSet(context.Context, *KVSetRequest) (*KVSetResponse, error)
	KVDelete(context.Context, *KVDeleteRequest) (*KVDeleteResponse, error)
	KVList(context.Context, *KVListRequest) (*KVListResponse, error)
	// kv batch (grant "kv", CONTRACTS §93): many keys of ONE namespace in one
	// call. The host checks the grant once and makes one Redis round trip
	// (MGET, one host-owned script, DEL), so the cost does not grow with the
	// number of keys the way N single calls do.
	//
	//   - Namespace, key, value and ttl rules are those of the single calls.
	//     At most 512 keys or items per call, and at most 3 MiB of keys plus
	//     values in one KVSetMany; otherwise INVALID_ARGUMENT. A key may
	//     repeat: KVGetMany answers every occurrence, KVSetMany keeps the
	//     last one. No keys is valid and does nothing.
	//   - KVGetMany answers one item per requested key, in request order.
	//     When the values found add up to more than 3 MiB the call fails with
	//     RESOURCE_EXHAUSTED and the caller asks for fewer keys (48 keys
	//     always fit).
	//   - KVSetMany is all or nothing: when any item is invalid nothing is
	//     written, otherwise every item is written with its own ttl in one
	//     atomic step. ttl_seconds is 0 (no expiry) up to 9223372036.
	//   - The script is the host's own. Plugins cannot submit scripts.
	KVGetMany(context.Context, *KVGetManyRequest) (*KVGetManyResponse, error)
	KVSetMany(context.Context, *KVSetManyRequest) (*KVSetManyResponse, error)
	KVDeleteMany(context.Context, *KVDeleteManyRequest) (*KVDeleteManyResponse, error)
	// secrets (grant "secrets"): seal / open small values (<= 64 KiB) with the
	// core master key (AES-256-GCM). The ciphertext is bound to the calling
	// plugin and to `context`, so another plugin, or another row of the same
	// plugin, cannot open it. The plugin stores the ciphertext itself, e.g. an
	// upstream API key in its own schema (CONTRACTS §72.2).
	SecretSeal(context.Context, *SecretSealRequest) (*SecretSealResponse, error)
	SecretOpen(context.Context, *SecretOpenRequest) (*SecretOpenResponse, error)
	// prices (grant "prices"): price token usage of a model with the core
	// model price table, exactly as gateway settlement would before the group
	// multiplier. Read only: nothing is charged or recorded (CONTRACTS §72.13.1).
	PriceUsage(context.Context, *PriceUsageRequest) (*PriceUsageResponse, error)
	// db.schema: the DSN of the plugin schema (CONTRACTS §115). Behind the
	// egress tunnel it is the virtual address db.sub2api:5432 without
	// credentials, which the core logs in to as its own database user with
	// search_path on the schema; without the tunnel (development) it is the
	// core's DSN with search_path pinned. The SDK dialer goes through
	// EgressService automatically.
	GetDSN(context.Context, *GetDSNRequest) (*GetDSNResponse, error)
	// authz: does a console user hold a permission? Own keys always; others
	// need authz.read.
	AuthzCheck(context.Context, *AuthzCheckRequest) (*AuthzCheckResponse, error)
	// Always granted: which accounts may the caller of a request act on? The
	// answer is the core's own account scope rule (CONTRACTS §21.0), so a
	// plugin route applies it instead of deciding by itself. user_id must be
	// the Caller of an HTTPService.HandleHTTP request this plugin is serving
	// when it asks; any other user is PERMISSION_DENIED, as is a user holding
	// account:<action> at no scope (not even own).
	AccountScopeCheck(context.Context, *AccountScopeCheckRequest) (*AccountScopeCheckResponse, error)
	// ledger.credit / ledger.debit: bounded by the approved scope
	// (maxPerTx, maxPerDay), idempotent on idempotency_key.
	LedgerCredit(context.Context, *LedgerChangeRequest) (*LedgerChangeResponse, error)
	LedgerDebit(context.Context, *LedgerChangeRequest) (*LedgerChangeResponse, error)
	// broadcast (grant "broadcast"): deliver a small message to this plugin's
	// instances on every other live node (AppService.OnBroadcast), best
	// effort, e.g. "rules changed, reload". Payload at most 64 KiB.
	Publish(context.Context, *PublishRequest) (*PublishResponse, error)
	// jobs (grant "jobs"): runtime tasks, the plugin's own
	// scheduled tasks besides manifest jobs[] (CONTRACTS §77.8). Each is the
	// cluster task plugin.<key>.<id>; a run calls AppService.RunJob with its
	// id, scope "cluster" and the task's args. Only the instance of the
	// plugin's active version changes them: the calls of an older or newer
	// version during a rollout succeed and change nothing.
	//
	// SyncTasks replaces all runtime tasks of the plugin with the given ones
	// (declarative; repeating it is harmless).
	SyncTasks(context.Context, *SyncTasksRequest) (*SyncTasksResponse, error)
	// UpsertTask adds or changes one runtime task.
	UpsertTask(context.Context, *UpsertTaskRequest) (*UpsertTaskResponse, error)
	// DeleteTask removes one runtime task; runs already queued do not run.
	DeleteTask(context.Context, *DeleteTaskRequest) (*DeleteTaskResponse, error)
	// ListTasks returns the runtime tasks of the plugin.
	ListTasks(context.Context, *ListTasksRequest) (*ListTasksResponse, error)
	// EnqueueTask submits one run of a runtime task or a cluster manifest job,
	// with its own args.
	EnqueueTask(context.Context, *EnqueueTaskRequest) (*EnqueueTaskResponse, error)
	// lock (grant "lock"): short cross-node mutual exclusion on the host's
	// Redis, for work that must not run on two nodes at once. Periodic work
	// belongs in manifest jobs[] instead (each trigger runs once cluster-wide).
	//
	//   - The host prefixes every name: the Redis key is
	//     lock:plugin:{plugin_key}:{name}, so plugins never see each other's
	//     locks. name must match ^[A-Za-z0-9._:/-]{1,128}$ and ttl_ms must be
	//     1000..300000, otherwise INVALID_ARGUMENT.
	//   - Validity is reported as a DURATION (valid_ms), counted by the host on
	//     its own clock from when it took or extended the lock, minus a drift
	//     margin - never as an absolute time, so plugin and host clocks do not
	//     have to agree. The plugin should count it from BEFORE it sent the
	//     request.
	//   - The locks are NOT fenced: a holder that stalls past its validity may
	//     find another node has taken the lock meanwhile, so the guarded work
	//     must still be idempotent.
	//   - The PLUGIN chooses the owner token: a fresh random value for every
	//     LockAcquire (at least 16 random bytes, e.g. from a CSPRNG, encoded
	//     as URL-safe base64 or hex), matching ^[A-Za-z0-9_-]{16,128}$. The
	//     host stores it as the lock's value in Redis. Because the plugin
	//     knows the token before it asks, a LockAcquire whose outcome is
	//     unknown (UNAVAILABLE, a deadline, a broken connection) can be undone
	//     with LockRelease(name, token) instead of blocking every other node
	//     until the ttl runs out.
	//   - Never reuse a token: a LockAcquire with the token of a lock this
	//     plugin ALREADY holds under that name fails the SET NX, and the
	//     cleanup of the failed attempt (a compare-and-delete with the same
	//     token) then deletes the held lock. The call answers acquired=false
	//     and nobody holds the lock afterwards.
	//   - The host keeps no state per lock: when the plugin process dies its
	//     locks lapse after their ttl.
	//   - Errors: no "lock" grant -> PERMISSION_DENIED; bad name, ttl or token
	//     -> INVALID_ARGUMENT; Redis unavailable or outcome unknown ->
	//     UNAVAILABLE (the lock may or may not be held - treat it as not held;
	//     after a LockAcquire, call LockRelease with the same token).
	//
	// LockAcquire makes ONE attempt, without waiting. acquired=false means
	// another holder has it; that is not an error.
	LockAcquire(context.Context, *LockAcquireRequest) (*LockAcquireResponse, error)
	// LockRenew extends a lock still held with token to ttl_ms from now.
	// held=false means the lock is definitely lost (expired, or held by
	// someone else); it is not an error.
	LockRenew(context.Context, *LockRenewRequest) (*LockRenewResponse, error)
	// LockRelease releases the lock only if it is still held with token.
	// Idempotent: releasing a lock that expired, was already released or was
	// never taken is not an error. UNAVAILABLE means the host could not tell
	// whether it was released; it then lapses after its ttl (or retry).
	LockRelease(context.Context, *LockReleaseRequest) (*LockReleaseResponse, error)
	// Metadata of the accounts of this plugin's account types; a plugin that
	// declares none gets an empty list. It is the list a plugin needs to offer
	// "pick an account" in its own console page. Paginated: at most 200 rows
	// per call (100 by default).
	ListAccounts(context.Context, *ListAccountsRequest) (*ListAccountsResponse, error)
	// The account of this plugin's own account types, as PlatformService calls
	// receive it: properties, settings, decrypted credentials and the proxy
	// (CONTRACTS §124). Another plugin's account, a deleted one or none at all
	// is NOT_FOUND. Audited on every call: the audit_logs row is written before
	// the account is returned, and a failed write fails the call. The proxy is
	// data: the plugin never connects through it itself.
	GetAccount(context.Context, *GetAccountRequest) (*GetAccountResponse, error)
	// The fetch form of the host's HTTP client: one non-streaming
	// HTTP exchange whose answer goes back to the plugin. For the auxiliary
	// requests of an Execute call (token exchange, upload, preflight) and the
	// upstream query of a Monitor call. Authority comes from the call's
	// execution token, not from a generic net/accounts permission.
	//
	// The URL must be http(s). Its host must be one of the manifest's
	// externalServices (or a subdomain of one), or the host of one of the
	// call's own account's upstream addresses: the values of the address
	// fields its account type declares (manifest upstreamFields), so that an
	// account an operator pointed at a relay can be queried there. No other
	// host is reachable. In both cases the host sends the request through the
	// account's proxy behind the SSRF guard - an account address naming a
	// private target is refused like any other unless the account's scope
	// allows it -, without the operator's header passthrough and override
	// (those describe the client's request, which this is not), and does not
	// follow redirects. The host neither counts the requests of a call nor
	// cuts their answers: the answer body comes back whole; nor does it bound
	// the request body (the request body limit applies to the client's
	// request in the gateway only). A transport
	// failure is not an RPC error: it comes back in transport_error with
	// status 0.
	//
	// A console route call (HTTPRequest.execution_token) may fetch too, for
	// the authorization of an account not saved yet: it has no account, so
	// only externalServices are reachable, and every fetch names the proxy
	// ticket the console issued (ExecutionHTTPRequest.proxy_ticket, CONTRACTS
	// §117).
	ExecuteHTTP(context.Context, *ExecutionHTTPRequest) (*ExecutionHTTPResponse, error)
	// One HTTP request for ONE account of this plugin's account types, sent
	// by the host through that account's proxy (behind netguard for a direct
	// connection), the same way as the quota and refresh requests the plugin
	// describes (CONTRACTS §91). The URL must be http(s) and its host one of
	// the manifest's externalServices (or a subdomain of one) or the host of
	// one of the account's own upstream addresses (manifest upstreamFields;
	// CONTRACTS §112.17). Redirects are not followed; the answer body comes back whole.
	// A transport failure is not an RPC error: it comes back in
	// transport_error with status 0.
	// Audited on every call (account, method, host and path; never headers or
	// bodies).
	SendAccountRequest(context.Context, *SendAccountRequestRequest) (*ExecutionHTTPResponse, error)
	mustEmbedUnimplementedHostServiceServer()
}

